import { test, expect } from '@playwright/test';

test.describe('Error Banner on API Failure', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display error banner when API call fails', async ({ page }) => {
    // Intercept the API call and simulate a failure
    await page.route('**/api/data', (route) => {
      route.abort('failed');
    });

    // Click the button that triggers the API call
    const fetchDataButton = page.getByRole('button', { name: /fetch data/i });
    await fetchDataButton.click();

    // Wait for the error banner to appear
    const errorBanner = page.getByText(/error/i);
    await expect(errorBanner).toBeVisible();

    // Verify the error message content
    const errorMessage = page.getByText(/failed to load data/i);
    await expect(errorMessage).toBeVisible();

    // Verify the error banner has appropriate styling
    const bannerContainer = page.locator('[data-testid="error-banner"]');
    await expect(bannerContainer).toHaveClass(/error-message/);

    // Verify the error banner has a close button
    const closeButton = page.getByRole('button', { name: /close/i });
    await expect(closeButton).toBeVisible();

    // Verify the error banner is dismissible
    await closeButton.click();
    await expect(errorBanner).not.toBeVisible();
  });

  test('should not display error banner when API call succeeds', async ({ page }) => {
    // Intercept the API call and simulate success
    await page.route('**/api/data', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({ data: 'Success' }),
      });
    });

    // Click the button that triggers the API call
    const fetchDataButton = page.getByRole('button', { name: /fetch data/i });
    await fetchDataButton.click();

    // Wait for the success message to appear
    const successMessage = page.getByText(/data loaded successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify the error banner does not exist
    const errorBanner = page.locator('[data-testid="error-banner"]');
    await expect(errorBanner).not.toBeVisible();

    // Verify the success message has appropriate styling
    const successContainer = page.locator('[data-testid="success-message"]');
    await expect(successContainer).toHaveClass(/success-message/);

    // Verify the success message is visible
    await expect(successMessage).toBeVisible();
  });
});
